svg.script:
function clamp(v,a,b){ return Math.max(a, Math.min(b,v)); }
function lerp(a,b,t){ return a + (b-a)*t; }
function smoothstep(t){ return t*t*(3-2*t); }

function init(evt){
  const svg = evt.target;
  const scene = svg.getElementById('scene');

  const xMin = 40, xMax = 960, step = 6;
  const xs = [];
  for(let x=xMin; x<=xMax; x+=step) xs.push(x);

  const L = 10;
  const layers = [];
  for(let i=0;i<L;i++){
    const depth = i/(L-1);
    const y0 = 95 + 460*depth;
    const opacity = 0.75*Math.pow(1-depth,1.05) + 0.05;
    const strokeW = 2.4 + 4.4*(1-depth);
    const blur = (depth>0.65);

    const p1 = document.createElementNS("http://www.w3.org/2000/svg","path");
    const p2 = document.createElementNS("http://www.w3.org/2000/svg","path");

    [p1,p2].forEach(p=>{
      p.setAttribute("fill","none");
      p.setAttribute("stroke","currentColor");
      p.setAttribute("stroke-linecap","round");
      p.setAttribute("stroke-linejoin","round");
      p.setAttribute("stroke-width", strokeW.toFixed(2));
    });

    p1.setAttribute("opacity", opacity.toFixed(3));
    p2.setAttribute("opacity", (opacity*0.78).toFixed(3));
    if(blur) p2.setAttribute("filter","url(#softFar)");

    scene.appendChild(p1);
    scene.appendChild(p2);

    const seed = 0.12 + i*0.27;
    layers.push({depth,y0,seed,p1,p2});
  }

  // draw far first
  for(let i=scene.children.length-1;i>=0;i--){
    scene.appendChild(scene.children[i]);
  }

  let running = true, elapsed = 0, lastNow = performance.now();

  let fLong = 0.10, fLocal = 0.28;
  let targetFL = fLong, targetFS = fLocal;
  let nextRetarget = 0;

  let dir = 1, targetDir = 1, nextDir = 0;

  function retarget(t){
    targetFL = lerp(0.06, 0.14, (Math.sin(t*0.21)+1)/2);
    targetFS = lerp(0.18, 0.45, (Math.sin(t*0.17+1.3)+1)/2);
    nextRetarget = t + lerp(2.8, 6.5, (Math.sin(t*0.13+0.7)+1)/2);

    if(t > nextDir){
      targetDir = (Math.random()<0.5) ? -1 : 1;
      nextDir = t + lerp(5.0, 11.0, Math.random());
    }
  }

  function gauss(x, mu, sigma){
    const z = (x-mu)/sigma;
    return Math.exp(-0.5*z*z);
  }

  function catmullToBezier(pts){
    if(pts.length<2) return "";
    let d = `M ${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
    for(let i=0;i<pts.length-1;i++){
      const p0 = pts[i-1] || pts[i];
      const p1 = pts[i];
      const p2 = pts[i+1];
      const p3 = pts[i+2] || p2;
      const c1x = p1[0] + (p2[0]-p0[0])/6;
      const c1y = p1[1] + (p2[1]-p0[1])/6;
      const c2x = p2[0] - (p3[0]-p1[0])/6;
      const c2y = p2[1] - (p3[1]-p1[1])/6;
      d += ` C ${c1x.toFixed(1)} ${c1y.toFixed(1)} ${c2x.toFixed(1)} ${c2y.toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
    }
    return d;
  }

  retarget(0);

  function frame(now){
    if(!running) return;
    const dt = Math.min(0.05, Math.max(0, (now-lastNow)/1000));
    lastNow = now;
    elapsed += dt;
    const t = elapsed;
    if(t > nextRetarget) retarget(t);

    // real-time frequency smoothing
    fLong += (targetFL - fLong) * 0.015;
    fLocal += (targetFS - fLocal) * 0.020;

    // smooth direction
    dir += (targetDir - dir) * 0.01;

    // fissure center (smooth) + direction
    const base = 0.5 - 0.5*Math.cos(2*Math.PI*(t*0.06 + 0.03*Math.sin(t*0.11)));
    const drift = 0.08*Math.sin(t*0.19) + 0.05*Math.sin(t*0.37+1.1);
    const center = lerp(160, 840, clamp(base + drift, 0, 1));
    const travel = (dir>=0) ? center : (1000 - center);

    for(const layer of layers){
      const d = layer.depth;
      const seed = layer.seed;

      const A_long = (10 + 3*Math.sin(2*Math.PI*(t*fLong) + seed) + 2*Math.sin(2*Math.PI*(t*(2*fLong)) + 1.7)) * (1 - 0.55*d);
      const A_local = (22 + 10*Math.sin(2*Math.PI*(t*fLong) + 0.9) + 7*Math.sin(2*Math.PI*(t*(2*fLong)) + 0.3)) * (1 - 0.78*d);

      const sigma = (110 + 18*Math.sin(t*0.7 + seed)) * (1 + 0.10*d);
      const sep = (26*(1-d) + 10) + 8*smoothstep(0.5 - 0.5*Math.cos(2*Math.PI*(t*0.09 + seed)));

      const phL = 2*Math.PI*(t*fLong) + 0.35*Math.sin(t*0.33 + seed);
      const phS = 2*Math.PI*(t*fLocal) + 0.45*Math.sin(t*0.27 + 0.4);

      const pull = (0.20 + 0.46*(0.5+0.5*Math.sin(t*0.55 + seed))) * (1 - 0.35*d);

      const pts1 = [];
      const pts2 = [];

      for(const x of xs){
        const g = gauss(x, travel, sigma);
        const yBase =
          layer.y0
          + A_long * Math.sin((x/560)*2*Math.PI + phL)
          + A_local * g * Math.sin((x/86)*2*Math.PI + phS)
          + (1.0 - 0.72*d) * (0.25+0.75*g) * 2.6 * Math.sin((x/260)*2*Math.PI + phS*0.41);

        const y1 = yBase - sep/2;
        pts1.push([x, y1]);

        const phL2 = phL + 0.60 + 0.25*Math.sin(t*0.41 + 0.2);
        const phS2 = phS + 0.95 + 0.35*Math.sin(t*0.63 + seed);
        const g2 = gauss(x, travel, sigma*1.55);

        let y2 =
          layer.y0
          + A_long*0.92 * Math.sin((x/560)*2*Math.PI + phL2)
          + A_local*0.90 * g2 * Math.sin((x/86)*2*Math.PI + phS2)
          + (1.0 - 0.72*d) * (0.25+0.75*g2) * 2.8 * Math.sin((x/260)*2*Math.PI + phS2*0.41)
          + sep/2;

        y2 = y2*(1 - pull*g2) + y1*(pull*g2);
        pts2.push([x, y2]);
      }

      layer.p1.setAttribute("d", catmullToBezier(pts1));
      layer.p2.setAttribute("d", catmullToBezier(pts2));
    }

    if(running) requestAnimationFrame(frame);
  }

  svg.baamEngine = {
    setPaused(paused){
      const next = !paused;
      if(next === running) return;
      running = next;
      if(running){ lastNow = performance.now(); requestAnimationFrame(frame); }
    },
    reset(){ elapsed = 0; lastNow = performance.now(); }
  };
  requestAnimationFrame(frame);
}
